export function resolveDegradedMode({providerHealth={},dbHealth='HEALTHY',storageHealth='HEALTHY'}={}){const down=Object.entries(providerHealth).filter(([,v])=>['DOWN','UNAVAILABLE'].includes(v)).map(([k])=>k);if(['DOWN','UNAVAILABLE'].includes(dbHealth))return {mode:'READ_ONLY_LAST_GOOD',reason:'DB_DOWN',disabled:['writes','personalization']};if(['DOWN','UNAVAILABLE'].includes(storageHealth))return {mode:'CONTROL_PLANE_ONLY',reason:'STORAGE_DOWN',disabled:['new_ingestion','heavy_history']};if(down.length)return {mode:'PARTIAL_PROVIDER_DEGRADED',reason:'PROVIDER_DOWN',providers:down};return {mode:'NORMAL',reason:'HEALTHY'}}
